    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def pos_from(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for kx, ky in (("x", "y"), ("row", "col"), ("r", "c"), ("i", "j")):
                if kx in obj and ky in obj and is_num(obj.get(kx)) and is_num(obj.get(ky)):
                    return (int(obj.get(kx)), int(obj.get(ky)))
            for k in ("pos", "position", "loc", "location", "coord", "coordinates"):
                p = pos_from(obj.get(k))
                if p is not None:
                    return p
            if "tile" in obj:
                p = pos_from(obj.get("tile"))
                if p is not None:
                    return p
        if isinstance(obj, (list, tuple)):
            if len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
                return (int(obj[0]), int(obj[1]))
        return None

    def extract_positions(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            p = pos_from(value)
            if p is not None:
                out.append(p)
                return out
            for v in value.values():
                out.extend(extract_positions(v))
            return out
        if isinstance(value, (list, tuple)):
            p = pos_from(value)
            if p is not None:
                out.append(p)
                return out
            for v in value:
                out.extend(extract_positions(v))
        return out

    def get_any(d, keys, default=None):
        if not isinstance(d, dict):
            return default
        for k in keys:
            if k in d:
                return d.get(k)
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def nearest(me, pts):
        best = None
        bd = None
        for p in pts:
            d = manhattan(me, p)
            if bd is None or d < bd:
                bd = d
                best = p
        return best, bd

